                description: A cursor-paginated page of selection-list items.
                required: [items, page]
                additionalProperties: false
                properties:
                  items:
                    type: array
                    description: The items on this page, ordered by `sort_order`.
                    items:
                      $ref: '#/components/schemas/SelectionListItem'
                  page:
                    $ref: '#/components/schemas/Page'
        '400':
          $ref: '#/components/responses/BadRequest'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '404':
          $ref: '#/components/responses/NotFound'
    post:
      operationId: createSelectionListItem
      summary: Add an item to a selection list
      description: >-
        Mints a `front_sli_`-prefixed id server-side. `code` must be unique within the
        list and is **immutable afterwards** (`409 CONFLICT` on a duplicate).
