_INGRESS_PATH_RE = re.compile(r"^\s*-?\s*path:\s*(?P<v>\S.*?)\s*$", re.MULTILINE)
_HELM_DEFAULT_RE = re.compile(r"""default\s+(['"])(?P<v>/[^'"]*)\1""")


