        '401': { $ref: '#/components/responses/Unauthorized' }
        '403': { $ref: '#/components/responses/Forbidden' }
        '500': { $ref: '#/components/responses/InternalError' }
    post:
      operationId: createPortal
      tags: [admin-portals]
      summary: Create (provision) a portal
      description: >-
        Provisions a new tenant portal via the resumable pipeline
        (org → Permit tenant → portal row → default subdomain → owner invite). The
        new portal starts `provisioned-pending-invite` (never silently `active`)
        and the owner invite dispatches with provisioning. `slug` is immutable and
        must be unique — a duplicate returns 409 `SLUG_TAKEN`. Permit
        **platform-admin** only.
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/PortalCreate' }
      responses:
        '201':
          description: Portal created (status = provisioned-pending-invite).
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Portal' }
        '400': { $ref: '#/components/responses/ValidationError' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '403': { $ref: '#/components/responses/Forbidden' }
        '409':
          description: A portal with this slug already exists (`SLUG_TAKEN`).
          content:
            application/json:
              schema: { $ref: '#/components/schemas/ErrorBody' }
        '500': { $ref: '#/components/responses/InternalError' }

