    out = []
    for rel, full in walk_files(root):
        if not rel.endswith((".yaml", ".yml")):
            continue
        text = read_text(full)
        if "kind: Ingress" not in text:
            continue
        out.append((rel, text))
    return out


def ingress_paths(text: str):
    """(literal_paths, unresolved_raw_values)."""
