            # fallback, and that fallback is what the chart ships when values are silent.
            d = _HELM_DEFAULT_RE.search(raw)
            if d:
                literal.append(d.group("v"))
            else:
                unresolved.append(raw)
        elif raw:
            unresolved.append(raw)
    return literal, unresolved


