      summary: Get the actor's Stripe customer credit balance
      description: >-
        Returns the Stripe customer credit balance for the actor entity (resolved
        from the proxy-injected actor context). Negative balance = available
        credit (Stripe convention). Returns `customerBalance: null` when no
        billing customer exists yet or when the provider is unavailable —
        callers should render the absence gracefully.
      security:
        - internalToken: []
      responses:
        '200':
          description: The customer balance (null when no customer or provider unavailable).
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [customerBalance]
                properties:
                  customerBalance:
                    nullable: true
                    type: integer
                    description: >-
                      Stripe customer balance in cents. Negative = available
                      credit; positive = amount owed. Null when no customer.
        '401':
          $ref: '#/components/responses/Unauthorized'

  /subscriptions/{subscriptionId}/revoke-cancellation:
    parameters:
      - $ref: '#/components/parameters/SubscriptionId'
    post:
      operationId: revokeCancellation
      tags: [subscriptions]
      summary: Revoke a scheduled cancellation
      description: >-
        Revokes a pending `cancel_at_period_end` on the subscription, re-activating
        it as a normal subscription. Mirrors `POST /subscriptions/:id/revoke-cancellation`.
      security:
        - internalToken: []
      responses:
        '200':
          description: The subscription mirror with cancellation revoked.
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [subscription]
                properties:
                  subscription:
                    $ref: '#/components/schemas/BillingSubscription'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '404':
          $ref: '#/components/responses/NotFound'
        '502':
          $ref: '#/components/responses/ProviderError'

  /subscriptions/{subscriptionId}/billing-anchor:
    parameters:
      - $ref: '#/components/parameters/SubscriptionId'
    patch:
      operationId: changeBillingAnchor
      tags: [subscriptions]
      summary: Change the billing cycle anchor day
      description: >-
        Changes the billing cycle anchor day (1–28). Stripe prorates the current
        cycle and restarts billing on the new anchor day each month.
        Mirrors `PATCH /subscriptions/:id/billing-anchor`.
      security:
        - internalToken: []
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/ChangeBillingAnchorRequest'
      responses:
        '200':
          description: The subscription mirror with the updated billing anchor.
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [subscription]
                properties:
                  subscription:
                    $ref: '#/components/schemas/BillingSubscription'
        '400':
          $ref: '#/components/responses/ValidationError'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '404':
          $ref: '#/components/responses/NotFound'
        '502':
          $ref: '#/components/responses/ProviderError'

  /setup-intent:
    post:
      operationId: createSetupIntent
      tags: [payment-methods]
      summary: Create a SetupIntent to collect a payment method
      description: >-
        Creates a provider SetupIntent (usage `off_session`) so the client can
        collect a payment method without an immediate charge (e.g. add a card
        during a no-card trial). Returns the `clientSecret` for the provider
        Payment Element. Mirrors `POST /setup-intent`.
      security:
        - internalToken: []
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/EntityRef'
      responses:
        '200':
          description: SetupIntent created.
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [clientSecret]
                properties:
                  clientSecret:
                    type: string
                    description: provider SetupIntent client secret for the Payment Element.
        '400':
          $ref: '#/components/responses/ValidationError'
        '422':
          $ref: '#/components/responses/IdentityError'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '502':
          $ref: '#/components/responses/ProviderError'

  /checkout:
    post:
      operationId: createCheckoutSession
      tags: [checkout]
      summary: Create a hosted Checkout Session (subscription mode)
      description: >-
        Creates a hosted Checkout Session in `subscription` mode for the
        given organization and plan, and returns the provider-hosted `url` to
        redirect the customer to. the provider collects the card on its hosted page;
        on completion the provider fires `checkout.session.completed`, which activates
        the local subscription mirror. We use HOSTED Checkout (not in-app
        Elements) so no raw card data touches our surface. Mirrors
        `POST /checkout`.


        Authorization (money path): the host proxy authenticates the platform
        JWT, authorizes the caller against the target organization, and forwards
        the SERVER-DERIVED actor + entity as trusted headers
        (`X-Billing-Actor-User-Id`, `X-Billing-Entity-Type`,
        `X-Billing-Entity-Id`; short aliases `X-FF-Actor-Id` / `X-FF-Org-Id`).
        The service RE-VERIFIES that `organizationId` matches the authorized
        entity before creating any provider object (rejects with 403 otherwise),
        and validates `planId` against the active plan catalogue (rejects
        unknown/inactive plans with 400). `planId: "basic"` resolves to the live
        $9/mo price.
      security:
        - internalToken: []
      parameters:
        - $ref: '#/components/parameters/ActorUserIdHeader'
        - $ref: '#/components/parameters/EntityTypeHeader'
        - $ref: '#/components/parameters/EntityIdHeader'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/CheckoutSessionRequest'
      responses:
        '200':
          description: Checkout Session created.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/CheckoutSessionResponse'
        '400':
          $ref: '#/components/responses/ValidationError'
        '422':
          $ref: '#/components/responses/IdentityError'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '502':
          $ref: '#/components/responses/ProviderError'

  /payments/checkout:
    post:
      operationId: createPaymentCheckoutSession
      tags: [payments]
      summary: Create a hosted Checkout Session (one-time payment mode)
      description: >-
        Creates a hosted Checkout Session in `payment` mode for an
        allowlisted consumer product (e.g. `mendys-datasets`) and returns the
        provider-hosted `url` to redirect the buyer to. The caller supplies the
        priced line items (name + unit amount in cents + quantity); the service
        builds provider `price_data` from them — no provider price catalogue entry
        is required. On completion the provider fires `checkout.session.completed`
        (mode `payment`), which upserts the local `billing.payments` mirror and
        emits `billing.payment.completed` on Kafka. Failure/expiry are mirrored
        via `payment_intent.payment_failed` / `checkout.session.expired`.
        Mirrors `POST /payments/checkout`.


        Authorization (money path): identical to `/checkout` — the host proxy
        authenticates the platform JWT, authorizes the caller against the
        target entity, and forwards the SERVER-DERIVED actor + entity as
        trusted headers (`X-Billing-Actor-User-Id`, `X-Billing-Entity-Type`,
        `X-Billing-Entity-Id`; aliases `X-FF-Actor-Id` / `X-FF-Org-Id`). The
        service RE-VERIFIES that the body's `entityType`/`entityId` match the
        authorized entity before creating any provider object (mismatch → 403).
        `productKey` must be in the server-side allowlist
        (`BILLING_PRODUCT_KEYS`), `currency` in the configured allowlist
        (default `usd`, `eur`), and each line amount plus the order total are
        bounded server-side (`BILLING_PAYMENT_MAX_TOTAL_CENTS`, default
        5,000,000 cents) — violations → 400.


        Idempotency: retries with IDENTICAL parameters dedupe to one provider
        session (param-fingerprint idempotency key, same scheme as
        `/checkout`); any changed parameter yields a fresh session.
      security:
        - internalToken: []
      parameters:
        - $ref: '#/components/parameters/ActorUserIdHeader'
        - $ref: '#/components/parameters/EntityTypeHeader'
        - $ref: '#/components/parameters/EntityIdHeader'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/PaymentCheckoutRequest'
      responses:
        '200':
          description: Payment-mode Checkout Session created.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/PaymentCheckoutResponse'
        '400':
          $ref: '#/components/responses/ValidationError'
        '422':
          $ref: '#/components/responses/IdentityError'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '409':
          description: Idempotency-key conflict (same key, different params).
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/ProviderErrorBody'
        '502':
          $ref: '#/components/responses/ProviderError'

  /payments/sessions/{sessionId}:
    parameters:
      - name: sessionId
        in: path
        required: true
        description: The hosted Checkout Session id (`cs_...`).
        schema:
          type: string
    get:
      operationId: getPaymentSession
      tags: [payments]
      summary: Get the local payment mirror for a Checkout Session
      x-pagination: exempt
      description: >-
        Returns the `billing.payments` mirror row for a payment-mode Checkout
        Session — the reconciliation-polling surface for consumer services
        that missed (or cannot receive) the `billing.payment.completed` event.
        `status` is `pending` until a webhook lands, then `paid` / `failed` /
        `expired`. 404 when the session is unknown. When the local row is
        missing but the session exists at the provider AND its `productKey` metadata
        is allowlisted, the service falls back to the live provider, re-mirrors the
        row, and returns it (singleton resource — pagination exempt).


        Authorization: same model as `/payments/checkout`; the proxy-authorized
        entity must OWN the session (mismatch → 403).
      security:
        - internalToken: []
      parameters:
        - $ref: '#/components/parameters/ActorUserIdHeader'
        - $ref: '#/components/parameters/EntityTypeHeader'
        - $ref: '#/components/parameters/EntityIdHeader'
      responses:
        '200':
          description: The payment mirror row.
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [payment]
                properties:
                  payment:
                    $ref: '#/components/schemas/BillingPayment'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
        '502':
          $ref: '#/components/responses/ProviderError'

  /credits:
    post:
      operationId: addCredits
      tags: [credits]
      summary: Add a one-time customer balance adjustment (admin only)
      description: >-
        Adds a one-time customer balance adjustment (credit) via a provider
        customer balance transaction. A positive `amount` (in cents, bounded)
        credits the customer (reduces what they owe). Mirrors `POST /credits`.


        ADMIN-ONLY: in addition to the internal token, the host proxy must
        supply `X-Billing-Actor-Is-Admin: true` (it sets this only for callers
        it has authorized as platform admins). Without it the service responds
        403. `amount` must be a positive integer and is capped server-side.
      security:
        - internalToken: []
      parameters:
        - name: X-Billing-Actor-Is-Admin
          in: header
          required: true
          schema:
            type: string
            enum: ['true']
          description: >-
            Set to `true` by the proxy ONLY for platform-admin-authorized
            callers. Required — absent/other values are rejected with 403.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/AddCreditsRequest'
      responses:
        '201':
          description: Balance transaction created.
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [id, endingBalance]
                properties:
                  id:
                    type: string
                    description: payment-provider customer balance transaction id.
                  endingBalance:
                    type: integer


