paths:
  /v1/selection-lists:
    get:
      operationId: listSelectionLists
      summary: List selection lists in the caller's organization
      description: >-
        Cursor-paginated. Scoped to the caller's organization and further
        filtered to the lists the caller can `read`; a list the caller has no
        grant on is simply absent, never a `403`. Each row carries its
        source-locale-resolved (or `locale`-resolved) `name`.
      tags: [lists]
      x-permit-action: read
      parameters:
        - name: limit
          in: query
          required: false
          description: >-
            Maximum rows to return. Clamped to `maximum` server-side — an
            over-max request is never honoured unbounded.
          schema:
            type: integer
            description: Page size.
            minimum: 1
            default: 50
            maximum: 200
        - name: cursor
          in: query
          required: false
          description: >-
            Opaque, server-issued cursor from the previous page's
            `page.nextCursor`. Echo it back unmodified; never construct or parse
            one. A malformed or expired cursor is a `400 VALIDATION_ERROR`,
            never a silent reset to page 1.
          schema:
            type: string
            description: Opaque pagination cursor.
            maxLength: 2048
        - name: status
          in: query
          required: false
          description: Filter lists by lifecycle status. Defaults to `active`.
          schema:
            type: string
            description: Lifecycle status filter.
            enum: [active, archived, all]
            default: active
        - name: locale
          in: query
          required: false
          description: >-
            Preferred locale for resolved text. Highest priority in the fallback
            chain; an unsupported value is a `400 VALIDATION_ERROR` rather than a
            silent fallback, so a client bug does not masquerade as missing
            translations.
          schema:
