--- deploy/argocd/applications/fuzefront.yaml ---
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  name: fuzefront
  namespace: argocd
spec:
  project: fuzefront
  source:
    repoURL: https://github.com/izzywdev/FuzeFront.git
    targetRevision: master
    path: deploy/helm/fuzefront
    helm:
      valueFiles:
        - values-prod.yaml
  destination:
    server: https://kubernetes.default.svc
    namespace: fuzefront
  syncPolicy:
