        with no ambiguous interleaving when two editors reorder concurrently.
      tags: [items]
      x-permit-action: update_value
      requestBody:
        required: true
        description: The complete, ordered list of non-archived item ids.
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/SelectionListItemReorder'
      responses:
        '200':
          description: The full reordered set of non-archived items.
          content:
            application/json:
              schema:
                type: object
                description: The reordered items, in their new order.
                required: [items]
                additionalProperties: false
                properties:
                  items:
                    type: array
                    description: Every non-archived item, in its new `sort_order`.
                    items:
                      $ref: '#/components/schemas/SelectionListItem'
        '400':
          $ref: '#/components/responses/BadRequest'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'

