        portal is refused with 409 `ROOT_PORTAL_PROTECTED`. Permit
        **platform-admin** only.
      responses:
        '200':
          description: Portal suspended.
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Portal' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '403': { $ref: '#/components/responses/Forbidden' }
        '404': { $ref: '#/components/responses/NotFound' }
        '409':
          description: The root portal cannot be suspended (`ROOT_PORTAL_PROTECTED`).
          content:
            application/json:
              schema: { $ref: '#/components/schemas/ErrorBody' }
        '500': { $ref: '#/components/responses/InternalError' }

  /api/v1/admin/portals/{portalId}/resume:
    parameters:
      - $ref: '#/components/parameters/PortalId'
    post:
      operationId: resumePortal
      tags: [admin-portals]
      summary: Resume a suspended portal
      description: >-
        Semantic lifecycle action equivalent to `PATCH .../{portalId}` with
        `{ "status": "active" }`. Flips a `suspended` portal back to `active` and
